class Solution:
    def rotate(self, m):
        n = len(m)
        for i in range(n):
            for j in range(i + 1, n):
                m[i][j], m[j][i] = m[j][i], m[i][j]
        for row in m:
            row.reverse()

def main():
    n = int(input())
    m = [list(map(int, input().split())) for _ in range(n)]
    Solution().rotate(m)
    for row in m:
        print(*row)


if __name__ == "__main__":
    main()
